const dsl = `workspace "Library" "A small public library system." {
    model {
        patron = person "Patron" "Borrows books at the library."
        library = softwareSystem "Library" "Manages books and loans." {
            catalog = container "Catalog Web App" "Lets patrons browse the catalogue." "Python"
            circulation = container "Circulation Service" "Records loans and returns." "Java"
        }
        patron -> catalog "Browses the catalogue through" "HTTPS"
        catalog -> circulation "Records loans via" "gRPC"
    }
    views {
        systemContext library "SystemContext" {
            include *
            autoLayout
        }
    }
}`;

const results = {};
try {
  results.plantuml = await tools.structurizr["export-plantuml"]({ dsl, viewKey: "SystemContext" });
} catch (e) { results.plantuml_error = String(e); }
try {
  results.c4plantuml = await tools.structurizr["export-c4plantuml"]({ dsl, viewKey: "SystemContext" });
} catch (e) { results.c4plantuml_error = String(e); }
try {
  results.mermaid = await tools.structurizr["export-mermaid"]({ dsl, viewKey: "SystemContext" });
} catch (e) { results.mermaid_error = String(e); }

// Test internet connectivity to PlantUML server
try {
  const r = await fetch("https://www.plantuml.com/plantuml/svg/~1", { method: "GET" });
  results.connectivity = { status: r.status, ok: r.ok };
} catch (e) {
  results.connectivity_error = String(e);
}

return results;

